const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(x,d=1)=>Number.isFinite(x)?x.toFixed(d):'—';
export function taskCsv(b){const fields=['id','load_id','destination','vehicle_id','state','reason','priority','created_s','assigned_s','ended_s','queue_wait_s','traffic_wait_s','held_s','travel_s','handling_s','distance_est_m','velocity_residual_s','pose_gap_s','peak_fork_load_n','stop_count','recovery_count','replans','tyre_mu_min','tyre_mu_max','road_mu_min','road_mu_max'];const q=x=>'"'+String(x??'').replaceAll('"','""')+'"';return [['run_id','scenario_id','cargo_mass_kg',...fields],...(b?.tasks??[]).map(t=>[b.run_id,b.scenario_id,b.cargo_mass_kg,...fields.map(k=>t[k])])].map(r=>r.map(q).join(',')).join('\n');}
const labels={pending:'대기열',assigned:'차량 배정',active:'수행 중',paused:'정지·복구 대기',failed:'고장 보류',completed:'완료',cancelled:'취소',interrupted:'Play 종료'};
export function taskRows(b){return (b?.tasks??[]).slice(-100).map(t=>`<tr><td>${esc(t.id)}<br>우선 ${t.priority}</td><td>${esc(t.load_id)}<br>→ ${esc(t.destination||'자동 선택')}</td><td>${esc(t.vehicle_id||'미배정')}</td><td>${esc(labels[t.state]??t.state)}<br>${esc(t.reason)}${t.recovery_required?'<br>Unreal에서 수동 복구 필요':''}</td><td>${n(t.queue_wait_s)} / ${n(t.traffic_wait_s)} s</td><td>${n(t.elapsed_s)} s<br>${n(t.distance_est_m,2)} m</td><td>${t.stop_count} / ${t.recovery_count}</td><td>${t.state==='pending'?`<button data-cancel-task="${esc(t.id)}">대기 취소</button>`:''}</td></tr>`).join('');}
function download(text,name,type){const u=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function initTasks(root){
 root.innerHTML=`<h2>작업 등록·자동 배차</h2><p id="task-state">실제 Unreal 운영 데이터 수신 대기</p><form id="task-form" class="task-form"><label>팔레트<select id="task-load" required></select></label><label>목적 슬롯<select id="task-destination"><option value="">자동 선택</option></select></label><label>자동 선택 적재단<select id="task-tier"><option value="1">1단</option><option value="2">2단</option></select></label><label>우선순위(9 높음)<input id="task-priority" type="number" min="0" max="9" value="0" required></label><button id="task-add">묶음에 추가</button></form><div id="task-draft"></div><button id="task-send" disabled>묶음 등록 요청</button> <button id="task-clear">묶음 비우기</button><p id="task-message" role="status"></p><div id="task-kpi" class="task-kpi"></div><div id="task-energy"></div><p>대기 시간: 배정 전 / 통로 대기. 이동 거리는 신선한 위치 정합 속도의 적분 추정값입니다. 평균 시간은 완료한 작업만 포함합니다.</p><div class="table-scroll"><table><thead><tr><th>작업</th><th>팔레트·목적지</th><th>차량</th><th>상태·원인</th><th>대기</th><th>배정 후 시간·추정 거리</th><th>정지·복구</th><th>조작</th></tr></thead><tbody id="task-rows"></tbody></table></div><p>최근 100건 표시 · 고장 보류는 자동 재시작하지 않습니다. 주행 정지·복구는 Unreal에서 조작합니다.</p><button id="task-csv" disabled>운영 작업 CSV</button> <button id="task-json" disabled>현재 운영 기록 JSON</button><label>저장 운영 기록 비교 <input id="task-compare-files" type="file" accept=".json" multiple></label><div id="task-comparison"></div>`;
 const $=s=>root.querySelector(s);let frame=null,live=false,draft=[],pending=null,catalogue='',run=null;const msg=x=>$('#task-message').textContent=x;
 const formState=()=>{for(const e of $('#task-form').elements)e.disabled=!live||!!pending;$('#task-send').disabled=!live||(!pending&&!draft.length);$('#task-send').textContent=pending?'같은 요청 확인·재전송':'묶음 등록 요청';$('#task-clear').disabled=!!pending;};
 const showDraft=()=>{$('#task-draft').textContent=draft.map((t,i)=>`${i+1}. ${t.load_id} → ${t.destination||'자동 '+t.tier+'단'} (우선 ${t.priority})`).join(' · ');formState();};
 $('#task-form').addEventListener('submit',e=>{e.preventDefault();const t={load_id:$('#task-load').value,destination:$('#task-destination').value,priority:Number($('#task-priority').value),tier:Number($('#task-tier').value)};if(draft.length>=10||draft.some(v=>v.load_id===t.load_id)||!t.load_id){msg('묶음은 서로 다른 팔레트 1~10개로 구성하세요.');return;}draft.push(t);showDraft();});
 $('#task-clear').onclick=()=>{draft=[];showDraft();};
 async function submit(kind,extra){if(!frame||!live)return;const b=frame.fleet.task_board;pending??={request_id:crypto.randomUUID(),world_id:frame.source.world_id,run_id:b.run_id,...extra};formState();try{const r=await fetch(kind==='enqueue'?'/api/tasks':'/api/tasks/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pending)});const j=await r.json();if(!r.ok){msg(j.error);pending=null;formState();return;}msg('전송됨 · Unreal의 실제 등록 확인을 기다립니다.');}catch{msg('응답 미확인 · 같은 요청으로 재전송하거나 실제 작업 목록을 확인하세요.');formState();}}
 $('#task-send').onclick=()=>submit(pending?.task_id?'cancel_pending':'enqueue',{tasks:draft.map(t=>({...t}))});
 $('#task-rows').onclick=e=>{const button=e.target.closest('[data-cancel-task]');if(button&&!pending)submit('cancel_pending',{task_id:button.dataset.cancelTask});};
 $('#task-csv').onclick=()=>{const b=frame?.fleet?.task_board;if(b)download(taskCsv(b),`ForkliftSim-tasks-${b.run_id}.csv`,'text/csv;charset=utf-8');};
 $('#task-json').onclick=()=>{const b=frame?.fleet?.task_board;if(b)download(JSON.stringify(b,null,2),`ForkliftSim-operations-${b.run_id}.json`,'application/json');};
 $('#task-compare-files').onchange=async e=>{try{const records=await Promise.all([...e.target.files].slice(0,10).map(f=>f.text().then(t=>JSON.parse(t.replace(/^\uFEFF/,'')))));if(records.some(b=>b.schema!==1||b.source!=='unreal_task_board_v1'||!b.kpi))throw new Error('Unreal 운영 기록 JSON을 선택하세요.');$('#task-comparison').innerHTML='<p>선택한 저장 기록 · 조건이 다른 실행은 같은 시험으로 간주하지 않습니다.</p><div class="table-scroll"><table><tr><th>실행·조건</th><th>완료/등록</th><th>평균 운반</th><th>평균 대기</th><th>처리량(시뮬 시간당)</th><th>정지</th><th>최대 동시 이동 / 충전 완료</th></tr>'+records.map(b=>`<tr><td>${esc(b.scenario_id)}<br>${esc(b.run_id)}<br>${esc(b.traffic_policy??'whole_job')} · ${b.vehicles?.length??'—'}대<br>화물 ${n(b.cargo_mass_kg,0)}kg · 타이어 ${n(b.tyre_mu_initial,2)} / 노면 ${n(b.road_mu_initial,2)}</td><td>${n(b.kpi.completed,0)}/${n(b.kpi.submitted,0)}</td><td>${n(b.kpi.mean_cycle_s)} s</td><td>${n(b.kpi.mean_wait_s)} s</td><td>${n(b.kpi.throughput_per_sim_hour)}</td><td>${n(b.kpi.stop_events,0)}</td><td>${n(b.peak_measured_moving,0)} / ${n(b.energy?.completed_charges,0)}</td></tr>`).join('')+'</table></div>';}catch(err){msg(err.message);}};
 setInterval(async()=>{if(!pending)return;try{const r=await fetch('/api/task-requests').then(r=>r.json());const ack=r.requests.find(r=>r.request_id===pending.request_id);if(ack&&ack.status!=='pending_unreal'){msg(ack.status==='accepted'?`Unreal 수락 · ${(ack.task_ids??[]).join(', ')||'대기 취소 완료'}`:`${ack.status}: ${ack.reason}`);if(ack.status==='accepted')draft=[];pending=null;showDraft();}}catch{}},1000);
 return {update(F,isLive){frame=F;const b=F?.fleet?.task_board;live=!!(isLive&&b?.enabled);if(run&&b?.run_id!==run){draft=[];pending=null;msg('Play 세션이 변경됐습니다. 작업을 새로 등록하세요.');}run=b?.run_id??null;$('#task-state').textContent=b?`${live?'연결됨':'중단/오래된 기록 · 등록 불가'} · ${b.scenario_id} · 화물 ${b.cargo_mass_kg}kg · 자동 배차 ${b.auto_dispatch?'ON':'OFF'}`:'Unreal에서 Play를 시작하세요.';
 if(b){const busy=new Set(b.tasks.filter(t=>!['completed','cancelled','interrupted'].includes(t.state)||t.recovery_required).map(t=>t.load_id));const loads=b.loads.filter(l=>!l.moving&&!busy.has(l.id));const slots=F.fleet.slots.filter(s=>!s.pallet_id&&!s.reserved_by&&!s.blocked).sort((a,b)=>a.id.localeCompare(b.id));const sig=loads.map(l=>l.id).join()+'|'+slots.map(s=>s.id).join();if(sig!==catalogue){catalogue=sig;for(const [selector,items,blank] of [['#task-load',loads,false],['#task-destination',slots,true]]){const e=$(selector),v=e.value;e.innerHTML=(blank?'<option value="">자동 선택</option>':'')+items.map(i=>`<option value="${esc(i.id)}">${esc(i.id)}</option>`).join('');if([...e.options].some(o=>o.value===v))e.value=v;}}
 const energy=b.energy;$('#task-energy').innerHTML=energy?`<h3>배터리·충전</h3><p>${energy.enabled?'에너지 모델 ON':'에너지 모델 OFF'} · ${b.traffic_policy==='section_windows'?'구간 예약':'작업 전체 예약'} · 충전 완료 ${energy.completed_charges}회. 잔량은 Unreal의 모터·펌프 소비 에너지로 계산합니다.</p><div class="table-scroll"><table><tr><th>차량</th><th>잔량</th><th>전력</th><th>소비 / 충전</th><th>상태</th></tr>${energy.vehicles.map(v=>`<tr><td>${esc(v.vehicle_id)}</td><td>${n(v.soc*100,2)}%</td><td>${n(v.power_w)} W</td><td>${n(v.consumed_wh)} / ${n(v.charged_wh)} Wh</td><td>${esc(v.mode)} ${esc(v.reason)}</td></tr>`).join('')}</table></div>`:'';
 const k=b.kpi;$('#task-kpi').innerHTML=[['등록',k.submitted],['대기',k.pending],['수행·정지',k.active],['완료',k.completed],['고장 보류',k.failed],['현재 판정 성공률',Number.isFinite(k.resolved_success_fraction)?n(100*k.resolved_success_fraction)+'%':'—'],['평균 수행',n(k.mean_cycle_s)+' s'],['평균 대기',n(k.mean_wait_s)+' s'],['시뮬 시간당 완료',n(k.throughput_per_sim_hour)],['정지 횟수',k.stop_events]].map(([a,v])=>`<div>${a}<strong>${v}</strong></div>`).join('')+b.vehicles.map(v=>`<div>${esc(v.vehicle_id)} 가동률<strong>${n(100*v.utilization_fraction)}%</strong></div>`).join('');$('#task-rows').innerHTML=taskRows(b);$('#task-csv').disabled=!b.tasks.length;$('#task-json').disabled=false;}
 else{$('#task-energy').innerHTML='';$('#task-kpi').innerHTML='';$('#task-rows').innerHTML='';$('#task-csv').disabled=true;$('#task-json').disabled=true;catalogue='';}
 formState();}};
}
